import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root object
  const root = new Group();
  root.userData.handlers = {};

  // Store disposables for cleanup
  const disposables = [];

  // ---------- Textured Plane (Sprite) ----------
  const imageUrl = config.imageUrl;
  const planeAspect = 512 / 320; // width / height from atlas rect
  const planeGeom = new PlaneGeometry(planeAspect, 1);
  const planeMat = new MeshBasicNodeMaterial();
  planeMat.transparent = true;
  const planeMesh = new Mesh(planeGeom, planeMat);
  // Slight offset to avoid z-fighting with text
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);
  disposables.push(planeGeom, planeMat);

  // Load texture asynchronously, assign when ready
  let loadedTexture = null;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
    // Ensure texture gets disposed on cleanup
    disposables.push(() => {
      if (loadedTexture) loadedTexture.dispose();
    });
  }

  // ---------- Text Content ----------
  const textItems =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];

  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: (config.visual?.colors?.paper ?? '#e8ecf2'),
      align: 'center',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // ---------- Cinematic Primitives ----------
  const primitiveCleanups = [];

  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const { name, params } = prim;
      if (ctx.primitives && typeof ctx.primitives[name] === 'function') {
        const result = ctx.primitives[name](root, params);
        if (result?.cleanup) primitiveCleanups.push(result.cleanup);
        // Store timeline to kill later if present
        if (result?.timeline && result.timeline.kill) {
          primitiveCleanups.push(() => result.timeline.kill());
        }
      }
    }
  }

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometry, material, texture
    for (const d of disposables) {
      if (typeof d === 'function') {
        d();
      } else if (d && typeof d.dispose === 'function') {
        d.dispose();
      }
    }

    // Dispose text objects (they manage their own resources)
    for (const txt of textObjects) {
      if (txt && txt.parent) txt.parent.remove(txt);
    }

    // Kill any primitive timelines / cleanups
    for (const clean of primitiveCleanups) {
      try {
        clean();
      } catch (_) {}
    }

    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return root;
}
